import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type TrustGraphicProps = Record<string, any>;

const AvatarIcon = ({ color }: { color: string }) => (
  <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
    <path
      d="M12 12C14.21 12 16 10.21 16 8C16 5.79 14.21 4 12 4C9.79 4 8 5.79 8 8C8 10.21 9.79 12 12 12ZM12 14C9.33 14 4 15.34 4 18V20H20V18C20 15.34 14.67 14 12 14Z"
      fill={color}
    />
  </svg>
);

const TrustGraphic: React.FC<TrustGraphicProps> = ({
  backgroundColor = "#020617",
  transparentBackground = false,
  durationInSeconds = 8,
  brandName = "Malloy Studio",
  brandColor = "#4f46e5",
  accentColor = "#10b981",
  textColor = "#f8fafc",
  trustPillars = ["Quality", "Reliability", "Support", "Innovation", "Security", "Value"],
  orbitRadius = 380,
  particleSpeedMultiplier = 1,
}) => {
  
  useFontLoader(["Outfit", "Plus Jakarta Sans"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Center Coordinates
  const cx = width / 2;
  const cy = height / 2;

  // Base Animations
  const coreScale = spring({
    frame: frame - 15,
    fps,
    config: { damping: 14, stiffness: 100 },
  });

  const coreOpacity = interpolate(frame, [10, 25], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

  const numNodes = trustPillars.length;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "'Plus Jakarta Sans', sans-serif" }}>
      
      {/* BACKGROUND SVG LAYER (Lines & Particles) */}
      <svg style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%", overflow: "visible", transition: "none" }}>
        
        {/* Glow Definitions */}
        <defs>
          <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
            <feGaussianBlur stdDeviation="8" result="blur" />
            <feComposite in="SourceGraphic" in2="blur" operator="over" />
          </filter>
          <filter id="core-glow" x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation="25" result="blur" />
            <feComposite in="SourceGraphic" in2="blur" operator="over" />
          </filter>
        </defs>

        {trustPillars.map((_, i) => {
          const angle = (i / numNodes) * Math.PI * 2 - Math.PI / 2;
          
          // Floating effect
          const floatOffset = Math.sin((frame + i * 20) / 25) * 15;
          
          const nx = cx + Math.cos(angle) * orbitRadius;
          const ny = cy + Math.sin(angle) * orbitRadius + floatOffset;

          const dx = cx - nx;
          const dy = cy - ny;
          const lineLength = Math.sqrt(dx * dx + dy * dy);

          // Staggered appearances
          const nodeStartFrame = 30 + i * 8;
          
          // Line drawing
          const drawProgress = interpolate(
            frame,
            [nodeStartFrame + 10, nodeStartFrame + 40],
            [lineLength, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          const lineOpacity = interpolate(
            frame,
            [nodeStartFrame + 10, nodeStartFrame + 25],
            [0, 0.3],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Particles flowing from nodes to center
          const particleLoopDuration = 90 / particleSpeedMultiplier;
          // Offset each particle slightly differently
          const particleTime = frame + (i * (particleLoopDuration / numNodes));
          const normalizedProgress = (particleTime % particleLoopDuration) / particleLoopDuration;
          
          // Only show particle if the line has been drawn
          const particleActive = frame > nodeStartFrame + 30;
          
          const px = nx + dx * normalizedProgress;
          const py = ny + dy * normalizedProgress;

          // Fade particle in at node, out at center
          const particleOpacity = particleActive 
            ? interpolate(normalizedProgress, [0, 0.1, 0.8, 1], [0, 1, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" })
            : 0;

          return (
            <g key={`connection-${i}`} style={{ transition: "none" }}>
              {/* Connecting Line */}
              <line
                x1={nx}
                y1={ny}
                x2={cx}
                y2={cy}
                stroke={accentColor}
                strokeWidth={2}
                opacity={lineOpacity}
                strokeDasharray={lineLength}
                strokeDashoffset={drawProgress}
                style={{ transition: "none" }}
              />

              {/* Traveling Trust Particle */}
              <circle
                cx={px}
                cy={py}
                r={4}
                fill={accentColor}
                opacity={particleOpacity}
                filter="url(#glow)"
                style={{ transition: "none" }}
              />
            </g>
          );
        })}

        {/* Core Glow Element */}
        <circle
          cx={cx}
          cy={cy}
          r={120 * coreScale}
          fill={brandColor}
          opacity={0.15 * coreOpacity}
          filter="url(#core-glow)"
          style={{ transition: "none" }}
        />
      </svg>

      {/* HTML LAYER (Text and Avatars) */}
      <div style={{ position: "absolute", width: "100%", height: "100%", pointerEvents: "none", transition: "none" }}>
        
        {/* Nodes */}
        {trustPillars.map((pillar, i) => {
          const angle = (i / numNodes) * Math.PI * 2 - Math.PI / 2;
          const floatOffset = Math.sin((frame + i * 20) / 25) * 15;
          
          const nx = cx + Math.cos(angle) * orbitRadius;
          const ny = cy + Math.sin(angle) * orbitRadius + floatOffset;

          const nodeStartFrame = 30 + i * 8;
          const nodeScale = spring({
            frame: frame - nodeStartFrame,
            fps,
            config: { damping: 12, stiffness: 120 },
          });
          const nodeOpacity = interpolate(frame, [nodeStartFrame, nodeStartFrame + 15], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

          return (
            <div
              key={`node-${i}`}
              style={{
                position: "absolute",
                left: nx,
                top: ny,
                transform: `translate(-50%, -50%) scale(${nodeScale})`,
                opacity: nodeOpacity,
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                gap: "8px",
                transition: "none",
              }}
            >
              <div 
                style={{
                  width: "48px",
                  height: "48px",
                  borderRadius: "50%",
                  backgroundColor: `${brandColor}22`,
                  border: `1px solid ${brandColor}55`,
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  boxShadow: `0 4px 12px ${brandColor}22`,
                  transition: "none",
                }}
              >
                <AvatarIcon color={textColor} />
              </div>
              <span
                style={{
                  color: textColor,
                  fontSize: "18px",
                  fontWeight: 500,
                  letterSpacing: "0.5px",
                  backgroundColor: `${backgroundColor}99`,
                  padding: "4px 12px",
                  borderRadius: "100px",
                  backdropFilter: "blur(4px)",
                  border: `1px solid ${textColor}11`,
                  transition: "none",
                }}
              >
                {pillar}
              </span>
            </div>
          );
        })}

        {/* Central Brand Entity */}
        <div
          style={{
            position: "absolute",
            left: cx,
            top: cy,
            transform: `translate(-50%, -50%) scale(${coreScale})`,
            opacity: coreOpacity,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            backgroundColor: brandColor,
            width: "220px",
            height: "220px",
            borderRadius: "50%",
            boxShadow: `0 10px 40px ${brandColor}66, inset 0 0 0 4px rgba(255,255,255,0.1)`,
            transition: "none",
          }}
        >
          <div
            style={{
              position: "absolute",
              width: "100%",
              height: "100%",
              borderRadius: "50%",
              border: `2px dashed rgba(255,255,255,0.3)`,
              transform: `rotate(${frame * 0.5}deg)`,
              transition: "none",
            }}
          />
          <span 
            style={{ 
              color: "#ffffff", 
              fontSize: "32px", 
              fontWeight: 700, 
              fontFamily: "'Outfit', sans-serif",
              textAlign: "center",
              lineHeight: 1.1,
              padding: "20px",
              textShadow: "0 2px 10px rgba(0,0,0,0.3)",
              transition: "none",
            }}
          >
            {brandName}
          </span>
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default TrustGraphic;